<script setup lang="ts">import{inject,ref,onMounted,computed}from'vue';import type Keycloak from'keycloak-js';import{catalog,offers,errorMessage}from'./api';const kc=inject<Keycloak>('keycloak')!;const rows=ref<any[]>([]),manufacturers=ref<any[]>([]),total=ref(0),loading=ref(false),error=ref(''),q=ref(''),brand=ref(''),fuel=ref(''),offset=ref(0),selected=ref<any|null>(null),quote=ref<any|null>(null),quoteError=ref(''),quoteBusy=ref(false);const form=ref({vehiclePrice:'',downPayment:'0.00',residualValue:'0.00',currency:'EUR',durationMonths:36,annualInterestRateBasisPoints:500});const pages=computed(()=>Math.max(1,Math.ceil(total.value/12)));async function load(){loading.value=true;error.value='';try{const r=await catalog.list({limit:12,offset:offset.value,q:q.value||undefined,manufacturerId:brand.value||undefined,fuelType:fuel.value||undefined});rows.value=r.data.items;total.value=r.data.total}catch(e){error.value=errorMessage(e)}finally{loading.value=false}}async function detail(v:any){try{selected.value=(await catalog.detail(v.variantId)).data;quote.value=null;quoteError.value=''}catch(e){error.value=errorMessage(e)}}async function calculate(){if(!selected.value||!form.value.vehiclePrice||!form.value.residualValue){quoteError.value='Bitte Fahrzeugpreis und Restwert angeben.';return}quoteBusy.value=true;quoteError.value='';try{quote.value=(await offers.quote(selected.value.variantId,form.value)).data}catch(e){quoteError.value=errorMessage(e)}finally{quoteBusy.value=false}}function money(v:string,c='EUR'){return Number(v).toLocaleString('de-DE',{style:'currency',currency:c})}function label(s:string){return(s||'').replaceAll('_',' ')}onMounted(async()=>{await load();try{manufacturers.value=(await catalog.manufacturers()).data.items}catch(e){console.warn(e)}})</script><template><div class="shell"><header><a class="logo" @click="selected=null">A<span>AUTOFLOW<small>MOBILITY PLATFORM</small></span></a><nav><a @click="selected=null">Fahrzeuge</a><a href="http://localhost:8084/api/doc" target="_blank">Catalog API ↗</a></nav><div class="account"><i></i>{{kc.tokenParsed?.preferred_username}}<button @click="kc.logout()">Abmelden</button></div></header><main><template v-if="!selected"><section class="heading"><div><p class="eyebrow">DISCOVER YOUR NEXT DRIVE</p><h1>Fahrzeuge <em>im Überblick.</em></h1><p>Entdecke den AutoFlow Fahrzeugkatalog und finde dein passendes Modell.</p></div><strong>{{total}}<small>publizierte Varianten</small></strong></section><section class="filters"><input v-model="q" @input="offset=0;load()" placeholder="Marke, Modell oder Variante suchen …"/><select v-model="brand" @change="offset=0;load()"><option value="">Alle Hersteller</option><option v-for="m in manufacturers" :value="m.manufacturerId">{{m.name}}</option></select><select v-model="fuel" @change="offset=0;load()"><option value="">Alle Kraftstoffe</option><option value="petrol">Benzin</option><option value="diesel">Diesel</option><option value="electric">Elektro</option><option value="hybrid">Hybrid</option><option value="plug_in_hybrid">Plug-in-Hybrid</option></select></section><div class="result">{{total}} ERGEBNISSE <span>SEITE {{Math.floor(offset/12)+1}} / {{pages}}</span></div><div v-if="error" class="error">{{error}} <button @click="load">Erneut versuchen</button></div><div v-else-if="loading" class="empty">Fahrzeuge werden geladen …</div><div v-else-if="!rows.length" class="empty">Keine veröffentlichten Fahrzeuge gefunden.</div><section v-else class="grid"><article v-for="v in rows" :key="v.variantId" @click="detail(v)"><div class="visual"><span>{{v.manufacturer.code}}</span><b>↗</b><small>{{label(v.bodyStyle)}}</small></div><div class="card"><label>{{v.manufacturer.name}} · {{v.model.name}}</label><h2>{{v.name}}</h2><p>{{v.generation.name}}</p><div class="spec"><span>{{v.powerKw?v.powerKw+' kW':'Leistung n. a.'}}</span><span>{{label(v.fuelType)}}</span><span>{{label(v.transmission)}}</span></div><footer>Preis auf Anfrage <b>↗</b></footer></div></article></section><div class="pagination"><button :disabled="offset===0" @click="offset=Math.max(0,offset-12);load()">← Zurück</button>{{Math.floor(offset/12)+1}} / {{pages}}<button :disabled="offset+12>=total" @click="offset+=12;load()">Weiter →</button></div><p class="note">Live-Daten aus dem Vehicle Catalog Service · Preise sind nicht Bestandteil des Katalogs.</p></template><template v-else><button class="back" @click="selected=null;quote=null">← Fahrzeugkatalog</button><section class="hero"><div><p class="eyebrow">{{selected.manufacturer.name}} / {{selected.model.name}}</p><h1>{{selected.name}}</h1><p>{{selected.generation.name}} · {{label(selected.bodyStyle)}}</p></div><div class="hero-art">AF / {{selected.manufacturer.code}}</div></section><section class="detail"><div class="panel"><p class="eyebrow">TECHNICAL OVERVIEW</p><h2>Fahrzeugdaten</h2><div class="specgrid"><div><small>Hersteller</small><b>{{selected.manufacturer.name}}</b></div><div><small>Modell</small><b>{{selected.model.name}}</b></div><div><small>Generation</small><b>{{selected.generation.name}}</b></div><div><small>Leistung</small><b>{{selected.powerKw?selected.powerKw+' kW':'–'}}</b></div><div><small>Kraftstoff</small><b>{{label(selected.fuelType)}}</b></div><div><small>Getriebe</small><b>{{label(selected.transmission)}}</b></div><div><small>Sitzplätze</small><b>{{selected.seats??'–'}}</b></div><div><small>Gewicht</small><b>{{selected.curbWeightKg?selected.curbWeightKg+' kg':'–'}}</b></div><div><small>CO₂</small><b>{{selected.co2EmissionGPerKm?selected.co2EmissionGPerKm+' g/km':'–'}}</b></div></div></div><aside class="panel quote"><p class="eyebrow">OFFER / PRICING</p><h2>Leasing kalkulieren.</h2><p>Der Katalog besitzt keine Preise. Gib die Kalkulationswerte ein; Offer leitet die Anfrage an Pricing weiter.</p><form @submit.prevent="calculate"><label>Fahrzeugpreis (EUR)<input v-model="form.vehiclePrice" type="number" min=".01" step=".01" required placeholder="z. B. 30000.00"/></label><label>Anzahlung (EUR)<input v-model="form.downPayment" type="number" min="0" step=".01" required/></label><label>Restwert (EUR)<input v-model="form.residualValue" type="number" min="0" step=".01" required/></label><div class="pair"><label>Laufzeit<select v-model.number="form.durationMonths"><option :value="24">24 Monate</option><option :value="36">36 Monate</option><option :value="48">48 Monate</option><option :value="60">60 Monate</option></select></label><label>Zins p.a. (%)<input type="number" min="0" step=".01" :value="form.annualInterestRateBasisPoints/100" @input="form.annualInterestRateBasisPoints=Math.round(Number(($event.target as HTMLInputElement).value)*100)"/></label></div><button class="primary" :disabled="quoteBusy">{{quoteBusy?'Berechnung läuft …':'Leasingrate berechnen ↗'}}</button></form><p v-if="quoteError" class="error">{{quoteError}}</p><div v-if="quote" class="quote-result"><small>MONATLICHE RATE</small><strong>{{money(quote.monthlyAmount,quote.currency)}}</strong><p>Gesamtkosten inkl. Anzahlung <b>{{money(quote.totalCostIncludingDownPayment,quote.currency)}}</b></p></div></aside></section></template></main><div class="bottom">AUTOFLOW MOBILITY <span>VEHICLE CATALOG · OFFER · PRICING</span></div></div></template>